      "tipo": "GC",
      "causa_raiz": "Alocação massiva de memória gerenciada na Heap (5,42 MB no frame 1009), desencadeando uma coleta de lixo (Garbage Collection) bloqueante de 25.84 ms, o que somado ao tempo de CPU atinge quase 50 ms e quebra a meta de 33 FPS (30.3 ms). Isso é característico de instanciações sem pool (Instantiate/Destroy) ou métodos que retornam novos arrays e coleções a cada ciclo.",
      "codigo_refatorado": "using System.Collections.Generic;
using UnityEngine;

public class ProjectilePoolManager : MonoBehaviour
{
    [SerializeField] private GameObject prefab;
    [SerializeField] private int initialPoolSize = 100;

    private readonly Queue<GameObject> _pool = new Queue<GameObject>();
    private readonly Collider[] _hitBuffer = new Collider[16];

    private void Awake()
    {
        PrewarmPool();
    }

    private void PrewarmPool()
    {
        for (int i = 0; i < initialPoolSize; i++)
        {
            GameObject obj = Instantiate(prefab, transform);
            obj.SetActive(false);
            _pool.Enqueue(obj);
        }
    }

    public GameObject GetFromPool(Vector3 position, Quaternion rotation)
    {
        GameObject obj = _pool.Count > 0 ? _pool.Dequeue() : Instantiate(prefab);
        obj.transform.position = position;
        obj.transform.rotation = rotation;
        obj.SetActive(true);
        return obj;
    }

    public void ReturnToPool(GameObject obj)
    {
        obj.SetActive(false);
        _pool.Enqueue(obj);
    }

    public int CheckOverlapNonAlloc(Vector3 center, float radius, LayerMask mask)
    {
        // Evita Physics.OverlapSphere() que aloca um novo array a cada chamada
        return Physics.OverlapSphereNonAlloc(center, radius, _hitBuffer, mask);
    }
}",
      "explicacao_didatica": "Quando criamos e destruímos objetos ou geramos listas e textos novos a todo instante, a memória do computador fica cheia de 'lixo'. O Unity precisa congelar o jogo por uma fração de segundo para passar o 'caminhão de lixo' (Garbage Collector). No seu caso, foram descartados mais de 5 MB de uma vez só, pausando o jogo por quase 26 milissegundos. A solução é o Reuso (Object Pooling): criamos os objetos uma única vez no início e apenas os escondemos ou mostramos quando necessário, zerando a criação de lixo e mantendo a taxa de quadros estável."
    }
  ],
